ttp-request="uploadProduct" :disabled="uploading" :show-file-list="false"><el-button :loading="uploading">上传商品图片</el-button></el-upload></el-form-item><el-tag v-for="(file,i) in form.gallery||[]" :key="file" closable @close="form.gallery.splice(i,1);if(form.asset===file)form.asset=form.gallery[0]||'stapler'" @click="viewAttachment(file)">图片 {{i+1}}</el-tag></template></template><template v-else-if="mode==='stock'"><el-form-item label="调整数量（负数为出库）"><el-input-number v-model="form.quantity" :precision="0"/></el-form-item><el-form-item label="调整原因" required><el-input v-model="form.reason" type="textarea"/></el-form-item></template><template v-else-if="mode==='migration'"><el-form-item label="团队根代理编号"><el-input-number v-model="form.rootAgentId" :min="1" :precision="0"/></el-form-item><el-form-item label="目标商城"><el-select v-model="form.targetShopId"><el-option v-for="s in shops.filter(s=>s.id!==shopId)" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item><el-form-item label="迁移生效时间"><el-date-picker v-model="form.effectiveAt" type="datetime" value-format="YYYY-MM-DD HH:mm:ss"/></el-form-item><el-alert title="先生成完整代理和客户名单，再由平台审核。历史订单和账本保持原商城归属。" :closable="false"/></template><template v-else-if="['ship','exchange'].includes(mode)"><el-form-item label="快递公司"><el-select v-model="form.carrier"><el-option v-for="s in ['顺丰速运','中通快递','圆通速递','韵达快递']" :key="s" :value="s"/></el-select></el-form-item><el-form-item label="快递单号" required><el-input v-model="form.tracking"/></el-form-item></template><template v-else-if="mode==='pointReview'"><el-form-item label="处理结果"><el-radio-group v-model="form.release"><el-radio :value="true">解除冻结</el-radio><el-radio :value="false">继续冻结</el-radio></el-radio-group></el-form-item><el-form-item label="复核依据" required><el-input v-model="form.reason" type="textarea"/></el-form-item><el-alert title="解冻不清零日累计和频率计数；解除后原积分余额保持不变。" :closable="false"/></template><template v-else-if="mode==='review'"><el-form-item label="审核结果"><el-radio-group v-