import {listShops,query,command,detail,agencyCommand,attachment,channelRetry,startBackup,uploadFinance,staffLookup,auditDetail} from '@/api/hexu'
import {modules,labels,settingFields} from './modules'
const props=defineProps({module:{default:'overview'}}),config=modules[props.module]
const shopId=ref(2),shops=ref([]),rows=ref([]),recentOrders=ref([]),summary=ref({}),search=ref(''),loading=ref(false),error=ref(''),activeTab=ref(config.tabs?.[0][1]||''),drawer=ref(false),selected=ref({}),dialog=ref(false),mode=ref(''),form=ref({}),saving=ref(false),editing=ref(false)
