lta','残次变动'],['reason','原因'],['reference_id','关联单据'],['created_at','时间']];if(props.module==='settings'&&activeTab.value!=='rules')return [['id','编号'],['title','名称'],['status','状态'],['updated_at','更新时间']];return config.columns||[]})
