async function load(){clearTimeout(refreshTimer);if(shopId.value===0&&!['documents/points_rule','documents/points_risk','resources/points','resources/pointBatches','resources/pointLedger'].includes(activeTab.value))shopId.value=shops.value[0]?.id;loading.value=true;error.value='';try{if(props.module==='overview'){const [d,o]=await Promise.all([query('dashboard',shopId.value),query('orders',shopId.value)]);summary.value=d.data;recentOrders.value=o.data.slice(0,8)}else{const response=await query(activeTab.value==='resources/reconciliationLines'&&statementBatch.value?'statements/'+statementBatch.value+'/lines':activeTab.value||config.path,shopId.value);rows.value=response.data.map(x=>({...x,title:x.body?.name||x.body?.title||x.kind}))}}catch(e){error.value=e.message||'数据读取失败，请稍后重试'}finally{loading.value=false;if(activeTab.value==='resources/reconciliationBatches'&&rows.value.some(r=>['QUEUED','PROCESSING'].includes(r.status)))refreshTimer=setTimeout(load,5000)}}
