:true,startsAt:Date.now(),expiresAt:Date.now()+30*86400000},coupon:{type:'FULL_REDUCTION',quantity:100,expiresAt:Date.now()+30*86400000},system_parameter:{unpaidMinutes:15,autoReceiveDays:7,afterSalesDays:7,notifyPaid:true,notifyShipped:true,notifyRefund:true,notifyWithdrawal:true,notifyInventory:true}}[activeTab.value.replace('documents/','')]||{}),...row?.body,id:row?.id};for(const f of currentFields.value)if(f[2]==='json')form.value[f[0]]=JSON.stringify(row?.body?.[f[0]]||[]);dialog.value=true}
function editStaff(row){mode.value='staff';form.value={userId:row?.user_id||0,userName:row?.user_name||'',nickName:row?.nick_name||'',role:row?.role_code||'WAREHOUSE',enabled:true,reason:''};dialog.value=true}
async function lookupStaff(){try{const user=(await staffLookup(shopId.value,form.value.userName)).data;form.value.userId=user.user_id;form.value.nickName=user.nick_name;ElMessage.success('账号已核对')}catch(e){form.value.userId=0;ElMessage.error(e.message)}}
function editMarketing(){mode.value='marketing';form.value={customerId:0,skuId:'',qty:1,points:0,couponId:'',region:'',result:null};dialog.value=true}
async function submit(){if(saving.value||uploading.value)return;saving.value=true;try{if(mode.value==='marketing'){form.value.result=null;form.value.result=(await command('marketing-preview',{shopId:shopId.value,customerId:form.value.customerId,items:[{id:form.value.skuId,qty:form.value.qty}],points:form.value.points,couponId:form.value.couponId,address:{name:'金额试算',region:form.value.region,detail:'不创建订单'}})).data;return;}if(mode.value==='staff'&&!form.value.userId)throw new Error('请先核对后台账号');let op={staff:'staff-assign',statement:'reconcile-import',adjustment:'adjustment-propose',pointReview:'point-freeze-review',box:'sku-box-rules',product:'sku-save',stock:'stock-adjust',exchange:'exchange-ship',ship:'ship',inspect:'return-inspect',rule:'rule-create',setting:'document-save'}[mode.value];let data={...form.value,shopId:shopId.value};if(mode.value==='review'){op=props.module==='refunds'?'refund-review':props.module==='finance'?(activeTab.value==='resources/reconciliationAdjustments'?'adjustment-review':'withdraw-review'):'document-review';data.decision=data.approve?'APPROVED':'REJECTED'}if(mode.value==='statement'&&(!data.statementDate||!data.rows.length))throw new Error('请填写账单日期并上传明细文件');if(mode.value==='setting'){data.kind=activeTab.value.replace('documents/','');for(const f of currentFields.value)if(f[2]==='json'){try{data[f[0]]=JSON.parse(data[f[0]]||'[]')}catch{throw new Error(f[1]+'格式错误')}}}if(mode.value==='migration')await agencyCommand('team-migration',data);else if(mode.value==='review'&&activeTab.value==='documents/team_migration')await agencyCommand('team-migration/'+data.id+'/review',data);else await command(op,data);ElMessage.success('操作成功，数据已保存');dialog.value=false;await load()}catch(e){ElMessage.error(e.message||'操作失败')}finally{saving.value=false}}

async function showStatement(row){statementBatch.value=row.id;activeTab.value='resources/reconciliationLines';await load()}
function newStatement(){mode.value='statement';form.value={statementDate:new Date().toISOString().slice(0,10),rows:[]};dialog.value=true}
function statementTemplate(){const csv='\ufeff业务类型,业务单号,渠道流水,商户号,金额（分）\r\n';const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='对账导入模板.csv';a.click();URL.revokeObjectURL(url)}
async function readStatementFile(event){form.value.rows=[];try{const f=event.target.files?.[0];if(!f)return;if(f.size>2*1024*1024)throw new Error('账单文件不能超过2MB');const source=(await f.text()).replace(/^\ufeff/,'');const result=[];let row=[],field='',quoted=false;for(let i=0;i<source.length;i++){const c=source[i];if(c==='"'){if(quoted&&source[i+1]==='"'){field+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(field);field=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&source[i+1]==='\n')i++;row.push(field);if(row.some(x=>x.trim()))result.push(row);row=[];field=''}else field+=c}if(quoted)throw new Error('CSV引号不完整');row.push(field);if(row.some(x=>x.trim()))result.push(row);const header=result.shift()?.map(x=>x.trim());if(header?.join(',')!=='业务类型,业务单号,渠道流水,商户号,金额（分）')throw new Error('请使用导入模板中的列名和顺序');if(!result.length||result.length>5000)throw new Error('每批须为1至5000条');form.value.rows=result.map((r,i)=>{if(r.length!==5||!/^\d+$/.test(r[4].trim())||!Number.isSafeInteger(Number(r[4])))throw new Error('第'+(i+2)+'行字段或金额格式错误');const type=({'支付':'PAYMENT','退款':'REFUND','提现':'PAYOUT'}[r[0].trim()]||r[0].trim());if(!['PAYMENT','REFUND','PAYOUT'].includes(type)||r.slice(1,4).some(x=>!x.trim()))throw new Error('第'+(i+2)+'行业务信息不完整');return {type,businessId:r[1].trim(),channelRef:r[2].trim(),merchantNo:r[3].trim(),amount:Number(r[4])}})}catch(e){ElMessage.error(e.message)}}
async function uploadProof(options){uploading.value=true;try{const response=await uploadFinance(options.file,shopId.value,mode.value==='setting'&&activeTab.value==='documents/link_campaign'?'LINK_CONFIRMATION':'FINANCE');form.value.uploads=[...(form.value.uploads||[]),response.data.id];if(mode.value==='setting')form.value.confirmationFile=response.data.id;return response.data}catch(e){throw e}finally{uploading.value=false}}
function removeProof(file){form.value.uploads=(form.value.uploads||[]).filter(id=>id!==file.response?.id);if(form.value.confirmationFile===file.response?.id)form.value.confirmationFile=''}
async function recheckLine(row){try{await command('reconcile-recheck',{shopId:shopId.value,id:row.id});ElMessage.success('已按最新业务及回执核对');await load()}catch{}}

async function viewAttachment(id){try{const blob=await attachment(id);if(!blob.type.startsWith('image/')){const response=JSON.parse(await blob.text());throw new Error(response.msg||'资料读取失败')}closeAttachment();attachmentUrl.value=URL.createObjectURL(blob);imageDialog.value=true}catch(e){ElMessage.error(e.message)}}
function closeAttachment(){if(attachmentUrl.value)URL.revokeObjectURL(attachmentUrl.value);attachmentUrl.value=''}
function newMigration(){mode.value='migration';form.value={rootAgentId:0,targetShopId:null,effectiveAt:''};dialog.value=true}
async function toggleSku(row){try{await ElMessageBox.confirm(row.status==='ACTIVE'?'确认下架该商品？':'确认审核通过并上架该商品？','商品状态');await command('sku-status',{shopId:shopId.value,id:row.id,status:row.status==='ACTIVE'?'INACTIVE':'ACTIVE'});await load()}catch{}}
async function backupNow(){try{await startBackup();ElMessage.success('备份任务已启动，可刷新查看结果');await load()}catch{}}
async function retryChannel(row){try{await channelRetry(row.id);ElMessage.success('回执已处理');await load()}catch{}}
async function exportRows(){try{await command('export-audit',{shopId:shopId.value,resource:activeTab.value||config.path,rowCount:filteredRows.value.length,filter:search.value})}catch{return}const cols=columns.value;const escape=v=>'"'+String(v??'').replaceAll('"','""').replace(/^[=+@-]/,"'")+'"';const content='\ufeff'+[cols.map(c=>escape(c[1])).join(','),...filteredRows.value.map(r=>cols.map(c=>escape(c[2]==='money'?money(r[c[0]]):r[c[0]])).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=config.title+'.csv';a.click();URL.revokeObjectURL(url)}
